// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";
import { openEvents, readSseFrame } from "./backend-stream-fixture.js";

describe("durable scoped application domain events", () => {
  let fixture: BackendFixture, cookie: string, userId: string;
  beforeEach(async () => {
    fixture = await backendFixture({ limits: { streamPollMs: 10 } });
    const registered = await fixture.register();
    cookie = registered.cookie;
    userId = registered.user.id;
  });
  afterEach(async () => fixture.close());
  const publish = (
    payload: Parameters<BackendFixture["runtime"]["publishEvent"]>[0]["payload"] = { version: 1 },
    idempotencyKey = randomUUID(),
  ) => fixture.runtime.publishEvent({ userId, type: "document.updated", payload, idempotencyKey });

  it("T-AC-58 emits a durable domain event with an opaque recipient-bound cursor", async () => {
    const expected = await publish();
    const stream = await openEvents(fixture, cookie);
    try {
      expect(stream.response.headers.get("content-type")).toContain("text/event-stream");
      const frame = await readSseFrame(stream.reader, "domain");
      expect(frame.data).toEqual(expected);
      expect(frame.id).toMatch(/^v1\.\d+\.[A-Za-z0-9_-]+$/);
      expect(frame.id).not.toContain(userId);
    } finally {
      await stream.reader.cancel();
    }
  });

  it("T-AC-58 resumes after an acknowledged cursor across an actual store reopen", async () => {
    const first = await publish({ version: 1 });
    const stream = await openEvents(fixture, cookie);
    const frame = await readSseFrame(stream.reader, "domain");
    expect(frame.data).toEqual(first);
    await stream.reader.cancel();
    const second = await publish({ version: 2 });
    await fixture.restart();
    const resumed = await openEvents(fixture, cookie, frame.id);
    try {
      expect((await readSseFrame(resumed.reader, "domain")).data).toEqual(second);
    } finally {
      await resumed.reader.cancel();
    }
  });

  it("T-AC-58 replays a private publish once and rejects changed payload under its key", async () => {
    const key = randomUUID();
    const first = await publish({ version: 1 }, key);
    expect(await publish({ version: 1 }, key)).toEqual(first);
    await expect(publish({ version: 2 }, key)).rejects.toMatchObject({
      code: "IDEMPOTENCY_CONFLICT",
    });
  });

  it("T-AC-58 prevents browsers from forging domain/system publications", async () => {
    const response = await fixture.json(
      "/events",
      { userId, type: "deployment.succeeded", payload: { trusted: true } },
      { cookie },
    );
    expect(response.status).toBe(404);
  });

  it("T-AC-58 denies foreign-user cursors and never sends another user's payload", async () => {
    await publish({ private: "first-user" });
    const first = await openEvents(fixture, cookie);
    const cursor = (await readSseFrame(first.reader, "domain")).id;
    await first.reader.cancel();
    const other = await fixture.register({
      name: "Other app user",
      email: "events-other@example.test",
      password: "Synthetic-event-passphrase-192!",
    });
    const denied = await fixture.request("/events", {
      headers: { cookie: other.cookie, "last-event-id": cursor },
    });
    expect(denied.status).toBe(409);
    const expected = await fixture.runtime.publishEvent({
      userId: other.user.id,
      type: "document.updated",
      payload: { private: "other-user" },
      idempotencyKey: randomUUID(),
    });
    const own = await openEvents(fixture, other.cookie);
    try {
      expect((await readSseFrame(own.reader, "domain")).data).toEqual(expected);
    } finally {
      await own.reader.cancel();
    }
  });

  it("T-AC-58 denies malformed and modified cursor values before opening a stream", async () => {
    for (const cursor of [
      "1",
      "v1.0.invalid",
      "v1.999999999999999999999.invalid",
      "foreign-frame",
    ]) {
      const response = await fixture.request("/events", {
        headers: { cookie, "last-event-id": cursor },
      });
      expect(response.status).toBe(409);
    }
  });

  it("T-AC-59 revokes an established stream after the actual app session is signed out", async () => {
    await publish();
    const stream = await openEvents(fixture, cookie);
    await readSseFrame(stream.reader, "domain");
    expect((await fixture.json("/auth/sign-out", {}, { cookie })).status).toBe(200);
    const frame = await readSseFrame(stream.reader, "revoked");
    expect(frame.data).toEqual({ reason: "authorization_changed" });
    expect((await stream.reader.read()).done).toBe(true);
  });

  it("T-AC-55 T-AC-59 closes a stream rather than emitting data after lifecycle changes", async () => {
    await publish();
    const stream = await openEvents(fixture, cookie);
    await readSseFrame(stream.reader, "domain");
    fixture.lifecycle.available = false;
    fixture.lifecycle.epoch++;
    expect((await readSseFrame(stream.reader, "revoked")).data).toEqual({
      reason: "authorization_changed",
    });
    expect((await stream.reader.read()).done).toBe(true);
  });

  it("T-AC-58 rejects oversize UTF-8 payloads and unknown recipients without a durable publication", async () => {
    await expect(
      Promise.resolve().then(() => publish({ text: "🛰️".repeat(10000) })),
    ).rejects.toMatchObject({ status: 413 });
    await expect(
      fixture.runtime.publishEvent({
        userId: randomUUID(),
        type: "document.updated",
        payload: {},
        idempotencyKey: randomUUID(),
      }),
    ).rejects.toMatchObject({ status: 404 });
  });
});
